probe_source.origin-browser-legacy:
async () => {
  const ws = new WebSocket('ws://127.0.0.1:44591');
  ws.binaryType = 'arraybuffer';
  const once = type => new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timeout: ${type}`)), 5000);
    ws.addEventListener(type, e => { clearTimeout(timer); resolve(e); }, {once: true});
  });
  try {
    await once('open');
    let received = once('message'); ws.send('origin-web');
    const welcome = (await received).data;
    if (!(welcome instanceof ArrayBuffer) || welcome.byteLength !== 8) throw new Error('welcome');
    const id = new DataView(welcome).getBigUint64(0, true);
    const bytes = new Uint8Array(8 + 65536); bytes.set(new Uint8Array(welcome));
    for (let i=8; i<bytes.length; i++) bytes[i] = i % 251;
    received = once('message'); ws.send(bytes);
    const binary = new Uint8Array((await received).data);
    if (binary.length !== bytes.length || !binary.every((b,i)=>b===bytes[i])) throw new Error('binary changed');
    const text = btoa(String.fromCharCode(...new Uint8Array(welcome))) + 'Origin π / 世界';
    received = once('message'); ws.send(text);
    if ((await received).data !== text) throw new Error('text changed');
    const closing = once('close'); ws.close(1000, 'origin-browser');
    const closed = await closing;
    if (closed.code !== 1000 || !closed.wasClean) throw new Error('unclean close');
    return {passed:true, origin:location.origin, endpoint:ws.url, userId:id.toString(), binaryBytes:binary.length-8, text:'Origin π / 世界', close:{code:closed.code,wasClean:closed.wasClean}, userAgent:navigator.userAgent};
  } finally { if (ws.readyState < 2) ws.close(); }
}

probe_source.origin-browser-denial:
async () => {
  const ws = new WebSocket('ws://127.0.0.1:44591');
  let opened = false, errorEvents = 0;
  ws.addEventListener('open', () => { opened = true; ws.close(); });
  ws.addEventListener('error', () => errorEvents++);
  const closed = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => { ws.close(); reject(new Error('denial timeout')); }, 5000);
    ws.addEventListener('close', e => { clearTimeout(timer); resolve(e); }, {once:true});
  });
  if (opened || errorEvents !== 1 || closed.code !== 1006 || closed.wasClean) throw new Error('expected browser upgrade refusal');
  return {passed:true, origin:location.origin, endpoint:ws.url, opened, errorEvents, close:{code:closed.code,wasClean:closed.wasClean}, note:'Browser exposes denied HTTP upgrade as error/1006; raw-socket tests separately assert HTTP 403 body.'};
}
